import numpy as np

def sweep(close, thresholds, ks, end_day, wait=1, step=126):
    """Monthly committed means of cycles whose trading ends by end_day."""
    out = {}
    for th in thresholds:
        for k in ks:
            res = run(close, k, wait, step, open_at=th)
            inside = [r for s, r in res if s + 378 <= end_day]
            out[(th, k)] = round(float(np.mean(inside)) / 6, 6)
    return out
